class Solution:
    def returnToBoundaryCount(self, nums: List[int]) -> int:
        pos = ans = 0
        for x in nums:
            pos += x
            if pos == 0:
                ans += 1
        return ans

c.cpp:
class Solution {
public:
    int returnToBoundaryCount(vector<int>& nums) {
        long long pos = 0; int ans = 0;
        for (int x : nums) {
            pos += x;
            if (pos == 0) ans++;
        }
        return ans;
    }
};

